  background: #f5f5f6 !important; color: #6b6f7a !important;
  border: none !important; box-shadow: none !important; overflow: visible !important;
  border-radius: 15px !important;
}

/* 连发的消息之间的间距 */
.msg-bubble-wrapper.is-first,
