/* ============================================================
   ④ 引用：上方小灰气泡 + 弯线 + 蓝色“回复一则”
   ============================================================ */
.msg-reply-block { display: none !important; }
.msg-content-stack { display: flex !important; flex-direction: column; }
.msg-me   .msg-content-stack { align-items: flex-end; }
.msg-them .msg-content-stack { align-items: flex-start; }

/* 有引用时，气泡往里留 30px，引用条向外伸出，弯线一定落在引用条上 */
.msg-me   .msg-content-stack:has(.msg-reply-block-detached) { padding-left: 30px; }
.msg-them .msg-content-stack:has(.msg-reply-block-detached) { padding-right: 30px; }

.msg-reply-block-detached {
  display: flex !important; order: -1;
  position: relative; overflow: visible !important;
  align-self: stretch !important; max-width: none !important;
  margin: 26px 0 4px !important;
