.msg-reply-detached-text { color: #929297 !important; line-height: 1.35 !important; }

/* 左上：又粗又大的蓝色引号 */
.msg-reply-block-detached::before {
  content: "\201C" !important;
  position: absolute; left: 1px; bottom: calc(100% - 4px);
  font-family: Georgia, "Times New Roman", serif;
  font-size: 28px; line-height: 1; font-weight: 900; color: #0a7cff;
}
/* 蓝色小字「回复一则」 */
.msg-reply-block-detached::after {
  content: "回复一则";
