/* 弯线：我方连在气泡左侧，对方连在右侧 */
.msg-me .msg-content-stack:has(.msg-reply-block-detached) .bubble-me-custom::before {
  content: ""; position: absolute; right: 100%; bottom: 50%;
  width: 18px; height: calc(50% + 6px); box-sizing: border-box;
  border-left: 3px solid #d4d4d8; border-bottom: 3px solid #d4d4d8;
  border-bottom-left-radius: 14px; pointer-events: none;
