.msg-them .msg-content-stack:has(.msg-reply-block-detached) .bubble-them-custom::before {
  content: ""; position: absolute; left: 100%; bottom: 50%;
  width: 18px; height: calc(50% + 6px); box-sizing: border-box;
  border-right: 3px solid #dedee2; border-bottom: 3px solid #dedee2;
  border-bottom-right-radius: 14px; pointer-events: none;
