  border-radius: 6px !important;
}

/* 引用消息：分别调整双方头像位置 */
.msg-bubble-wrapper.msg-me:has(.msg-reply-block-detached) .msg-avatar-me-container {
  margin-top: 55px !important;
}
.msg-bubble-wrapper.msg-them:has(.msg-reply-block-detached) .msg-avatar-them-container {
  margin-top: 0 !important;
