}

/* 对方「思维链」胶囊：文字换成 id */
.nuo-thinking-arrow, .nuo-thinking-icon { display: none !important; }
.nuo-thinking-btn {
  background: transparent !important; border: none !important; box-shadow: none !important;
  padding: 0 0 0 2px !important; height: 20px;
  display: inline-flex !important; align-items: center;
}
.nuo-thinking-wrap { gap: 2px; --thinking-wrap-gap: 2px; }
.nuo-thinking-label { font-size: 0 !important; }
.nuo-thinking-label::after {
  content: "@urxuanivqe_o";
  font-family: -apple-system, "Helvetica Neue", Arial, sans-serif;
  font-size: 12.5px; color: #8e8e93;
