}
/* 有思维链时，头像往下对准气泡 */
.msg-bubble-wrapper:has(.nuo-thinking-wrap) .msg-avatar-them-container {
  margin-top: 22px !important;
}
/* 引用 + 思维链同时存在：思维链上移到最顶，引用条往下让位 */
.msg-content-stack:has(.msg-reply-block-detached) .nuo-thinking-wrap:not(.is-open) {
  transform: translateY(-51px);
}
.msg-content-stack:has(.nuo-thinking-wrap:not(.is-open)) .msg-reply-block-detached {
  transform: translateY(24px);
}

/* ============================================================
   ⑤ 表情反应：移到气泡上方，做成想法气泡（旧主题保留，已改灰）
   ============================================================ */
.msg-bubble-wrapper.has-reactions {
  margin-top: var(--react-gap) !important;
}

/* 徽章本体：正圆，紧贴气泡，带白边 */
.msg-reaction-badge {
  --ring: 1.5px;
  --ring-color: #fff;
  top: auto !important;
  bottom: calc(100% + var(--react-y)) !important;
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  box-sizing: border-box !important;
  min-width: 22px !important;
  height: 22px !important;
  padding: 0 5px !important;
  border: none !important;
  border-radius: 999px !important;
  box-shadow: none !important;
  z-index: 3;
  filter:
    drop-shadow(var(--ring) 0 0 var(--ring-color))
    drop-shadow(calc(-1 * var(--ring)) 0 0 var(--ring-color))
    drop-shadow(0 var(--ring) 0 var(--ring-color))
    drop-shadow(0 calc(-1 * var(--ring)) 0 var(--ring-color)) !important;
}
.msg-reaction-emoji {
  font-size: 11px !important;
  line-height: 1 !important;
}
.msg-reaction-badge-me {
  left: calc(-1 * var(--react-x)) !important;
  right: auto !important;
  background: var(--me-bg) !important;
}
.msg-reaction-badge-them {
  right: calc(-1 * var(--react-x)) !important;
  left: auto !important;
  background: var(--them-bg) !important;
}
/* 尾巴：两颗圆点朝外 */
.msg-reaction-badge::before,
.msg-reaction-badge::after {
  content: "";
  position: absolute;
  border-radius: 50%;
  background: inherit;
}
.msg-reaction-badge::before { width: 8px; height: 8px; bottom: -2px; }
.msg-reaction-badge::after  { width: 4px; height: 4px; bottom: -8px; }
.msg-reaction-badge-them::before { right: -1px; left: auto; }
.msg-reaction-badge-them::after  { right: -7px; left: auto; }
.msg-reaction-badge-me::before { left: -1px; right: auto; }
.msg-reaction-badge-me::after  { left: -7px; right: auto; }

/* ============================================================
   ⑥ 语音：颜色 / 圆角同步新气泡（灰底 #f5f5f6 + 字 #6b6f7a + 圆角 15px），条已改短
   ============================================================ */
.voice-msg {
  background: transparent !important; padding: 0 !important; margin: 0 !important;
  border: none !important; box-shadow: none !important; position: relative !important;
  width: fit-content !important;
}
.bubble-me-custom:has(.voice-msg), .bubble-them-custom:has(.voice-msg),
.msg-bubble-container:has(.voice-msg), .msg-content-stack:has(.voice-msg) {
  background: transparent !important; border: none !important; box-shadow: none !important;
  padding: 0 !important; border-radius: 0 !important;
  width: fit-content !important;
}
/* 语音条自己是气泡，不再叠九宫格尾巴（转文字展开时不会多出一块灰） */
.bubble-me-custom:has(.voice-msg)::after,
.bubble-them-custom:has(.voice-msg)::after { display: none !important; }

.voice-msg .voice-controls-row {
  display: flex !important; align-items: center !important; gap: 4px !important;
  height: auto !important; min-height: 0 !important; max-height: none !important;
  width: fit-content !important; max-width: 100% !important;
  padding: 4px 10px !important; box-sizing: border-box !important;
  background: var(--them-bg) !important; color: var(--bubble-text) !important;
  border: none !important; border-radius: 15px !important; box-shadow: none !important;
  position: relative !important; z-index: 4 !important; pointer-events: none !important;
}
.msg-me .voice-msg .voice-controls-row { background: var(--me-bg) !important; }

/* 播放 / 下载按钮 */
.voice-msg .voice-play-btn {
  background: transparent !important; border: none !important; padding: 0 !important;
  width: 18px !important; height: 18px !important; flex-shrink: 0 !important;
  display: flex !important; align-items: center !important; justify-content: center !important;
  color: inherit !important; cursor: pointer !important; pointer-events: auto !important;
  position: relative !important; z-index: 5 !important;
}
.voice-msg .voice-download-btn {
  background: transparent !important; border: none !important; padding: 0 !important; margin: 0 !important;
  flex-shrink: 0 !important; opacity: .7 !important;
  display: flex !important; align-items: center !important; justify-content: center !important;
  color: inherit !important; cursor: pointer !important; pointer-events: auto !important;
  position: relative !important; z-index: 5 !important;
}
.voice-msg .voice-play-btn svg, .voice-msg .voice-download-btn svg {
  fill: currentColor !important; color: inherit !important;
}
.voice-msg .voice-play-btn svg { width: 15px !important; height: 15px !important; }
.voice-msg .voice-download-btn svg { width: 14px !important; height: 14px !important; }

/* 波形：已播放亮，未播放淡 */
.voice-msg .voice-waveform {
  display: flex !important; align-items: center !important; gap: 1px !important;
  height: 20px !important; flex: 0 0 auto !important; width: auto !important; min-width: 0 !important;
  position: relative !important; z-index: 2 !important; pointer-events: none !important;
}
.voice-msg .voice-waveform-bar {
  width: 1.5px !important; border-radius: 2px !important; flex-shrink: 0 !important;
  background: currentColor !important; opacity: .35 !important;
}
.voice-msg .voice-waveform-bar.active { opacity: 1 !important; }

/* 时长 */
.voice-msg .voice-duration {
  font-size: 10px !important; font-weight: 400 !important; color: inherit !important; opacity: .75 !important;
  flex-shrink: 0 !important; min-width: 0 !important; text-align: left !important;
  font-variant-numeric: tabular-nums !important;
  position: relative !important; z-index: 2 !important; pointer-events: none !important;
}

/* 转文字切换：整块透明覆盖可点击 */
.voice-msg .voice-transcription-toggle {
  display: block !important; width: 100% !important; height: 100% !important;
  background: transparent !important; border: none !important; padding: 0 !important; margin: 0 !important;
  position: absolute !important; top: 0 !important; left: 0 !important; z-index: 3 !important;
  font-size: 0 !important; color: transparent !important; overflow: hidden !important;
  cursor: pointer !important; pointer-events: auto !important;
}
.voice-msg .voice-transcription-toggle * { display: none !important; }
.voice-msg .voice-transcription-toggle::before,
.voice-msg .voice-transcription-toggle::after { content: none !important; display: none !important; }

/* 转文字框：和气泡同款 */
.voice-msg .voice-transcription {
  display: block !important; margin-top: 6px !important; margin-bottom: 0 !important;
  padding: 7px 14px !important; box-sizing: border-box !important; max-width: 100% !important;
  font-size: 13px !important; line-height: 1.4 !important;
  background: var(--them-bg) !important; color: var(--bubble-text) !important;
  border: none !important; border-radius: 15px !important; box-shadow: none !important;
  word-break: break-word !important; overflow-wrap: break-word !important;
  position: relative !important; z-index: 1 !important; cursor: pointer !important;
}
.msg-me .voice-msg .voice-transcription { background: var(--me-bg) !important; }
