/* 对齐 */
.msg-them .voice-msg { align-self: flex-start !important; }
.msg-me .voice-msg   { align-self: flex-end !important; }

/* ============================================================
   ⑦ 转账卡片：改成灰（上浅灰 / 下深一点灰，以分隔线为界）
   ============================================================ */
:root {
  --tf-top: #f5f5f6;      /* 上半：和气泡同色 */
  --tf-deep: #c4c4c4;     /* 下半 / 图标底 / 边框：和底栏图标同灰 */
  --tf-text: #8a8a8e;     /* 上半文字 */
  --tf-radius: 4px;
  --split: 73%;           /* 浅色区域占卡片高度的比例 */

  --transfer-card-width: 230px;
  --transfer-card-bg: #f5f5f6;
  --transfer-card-radius: 4px;
  --transfer-card-border: 1.5px solid #c4c4c4;
  --transfer-card-shadow: none;
  --transfer-icon-bg: #c4c4c4;
  --transfer-icon-color: #ffffff;
  --transfer-icon-size: 34px;
  --transfer-icon-svg-size: 18px;
  --transfer-amount-color: #8a8a8e;

  --transfer-success-card-bg: #f5f5f6;
  --transfer-success-card-border: 1.5px solid #c4c4c4;
  --transfer-success-icon-bg: #c4c4c4;
  --transfer-success-icon-color: #ffffff;
  --transfer-success-label-color: #8a8a8e;
  --transfer-rejected-card-bg: #f5f5f6;
  --transfer-rejected-card-border: 1.5px dashed #c4c4c4;
  --transfer-rejected-label-color: #b5b5ba;
  --transfer-expired-card-bg: #f5f5f6;
  --transfer-expired-card-border: 1.5px dashed #c4c4c4;
