/* 图片消息：紧贴照片的圆角卡片 + 往右上叠两层 */
:root {
  --img-card-bg: transparent;
  --img-card-pad: 0px;
  --img-card-radius: 16px;
  --img-photo-max-w: 170px;
  --img-photo-max-h: 220px;

  --img-w: 160px;          /* 实体图宽度 */
  --img-ratio: 3 / 4;
  --img-h: calc(var(--img-w) * 4 / 3);   /* 3:4 竖图 */
  --st-r: 16px;            /* 圆角 */
  --st-gap1: 9px;          /* 第二层往右露出多少 */
  --st-gap2: 18px;         /* 第三层往右露出多少 */
  --st-in1: 8px;           /* 第二层上下各缩进多少 */
  --st-in2: 16px;          /* 第三层上下各缩进多少 */

  --st-img1: url("https://imgbed.heliar.top/i/AoWSNPrYAvUTSCSf_IMG_1728.jpeg");
  --st-img2: url("https://imgbed.heliar.top/i/io2K1M6kBjymMS4Z_IMG_1726.jpeg");
  --st-f1: none;
  --st-f2: none;
}
body.dark-mode {
  --st-f1: grayscale(0.5) blur(1.5px) brightness(0.6);
  --st-f2: grayscale(0.9) blur(2.5px) brightness(0.45);
}

.msg-image-wrapper,
.msg-image-card {
  box-sizing: border-box !important;
  display: block !important;
  position: relative !important;
  isolation: isolate !important;
  min-width: 0 !important;
  min-height: 0 !important;
  max-width: 100% !important;
